package com.shiphappens.logistics.service;
import com.fasterxml.jackson.databind.ObjectMapper; import com.shiphappens.logistics.entity.*; import com.shiphappens.logistics.entity.Statuses.WebhookDeliveryStatus; import com.shiphappens.logistics.repository.*; import org.slf4j.*; import org.springframework.http.*; import org.springframework.scheduling.annotation.Async; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.*; import org.springframework.transaction.event.*; import org.springframework.web.client.RestClient; import javax.crypto.Mac; import javax.crypto.spec.SecretKeySpec; import java.nio.charset.StandardCharsets; import java.time.Instant; import java.util.*;
@Service public class WebhookService { private static final Logger log=LoggerFactory.getLogger(WebhookService.class); private final ShipmentRepository shipments; private final WebhookSubscriptionRepository subscriptions; private final WebhookDeliveryLogRepository deliveries; private final ObjectMapper json; private final RestClient http=RestClient.create(); public WebhookService(ShipmentRepository shipments,WebhookSubscriptionRepository subscriptions,WebhookDeliveryLogRepository deliveries,ObjectMapper json){this.shipments=shipments;this.subscriptions=subscriptions;this.deliveries=deliveries;this.json=json;}
 @Async("webhookExecutor") @TransactionalEventListener(phase=TransactionPhase.AFTER_COMMIT) public void shipmentChanged(ShipmentStatusChanged event){Shipment shipment=shipments.findById(event.shipmentId()).orElse(null);if(shipment==null)return;String eventId="EVT-"+UUID.randomUUID().toString().substring(0,12).toUpperCase();String type="SHIPMENT_"+event.status();for(WebhookSubscription subscription:subscriptions.findActiveForCustomer(shipment.getOrder().getCustomer()))deliver(subscription,shipment,eventId,type);}
 private void deliver(WebhookSubscription subscription,Shipment shipment,String eventId,String type){String payload;try{payload=json.writeValueAsString(Map.of("eventId",eventId,"eventType",type,"occurredAt",Instant.now().toString(),"shipmentId",shipment.getShipmentNumber(),"orderId",shipment.getOrder().getOrderNumber(),"status",shipment.getStatus().name()));}catch(Exception e){return;} for(int attempt=1;attempt<=3;attempt++){Integer httpStatus=null;String error=null;try{ResponseEntity<Void> response=http.post().uri(subscription.getTargetUrl()).contentType(MediaType.APPLICATION_JSON).header("X-Webhook-Signature",signature(payload,subscription.getSecret())).body(payload).retrieve().toBodilessEntity();httpStatus=response.getStatusCode().value();if(response.getStatusCode().is2xxSuccessful()){logDelivery(subscription,shipment,eventId,type,attempt,WebhookDeliveryStatus.SUCCESS,httpStatus,null);log.info("webhookDelivered eventId={} shipmentId={} attempt={}",eventId,shipment.getShipmentNumber(),attempt);return;}error="HTTP "+httpStatus;}catch(Exception ex){error="Delivery request failed";} WebhookDeliveryStatus status=attempt==3?WebhookDeliveryStatus.FAILED:WebhookDeliveryStatus.RETRYING;logDelivery(subscription,shipment,eventId,type,attempt,status,httpStatus,error);if(attempt<3)try{Thread.sleep(attempt*250L);}catch(InterruptedException e){Thread.currentThread().interrupt();return;}}log.warn("webhookFailed eventId={} shipmentId={} attempts=3",eventId,shipment.getShipmentNumber());}
 @Transactional(propagation=Propagation.REQUIRES_NEW) void logDelivery(WebhookSubscription subscription,Shipment shipment,String eventId,String type,int attempt,WebhookDeliveryStatus status,Integer httpStatus,String error){WebhookDeliveryLog log=new WebhookDeliveryLog();log.setSubscription(subscription);log.setShipment(shipment);log.setEventId(eventId);log.setEventType(type);log.setAttemptNumber(attempt);log.setStatus(status);log.setHttpStatus(httpStatus);log.setErrorMessage(error);deliveries.save(log);} private String signature(String payload,String secret){try{Mac mac=Mac.getInstance("HmacSHA256");mac.init(new SecretKeySpec(secret.getBytes(StandardCharsets.UTF_8),"HmacSHA256"));return HexFormat.of().formatHex(mac.doFinal(payload.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException("Cannot sign webhook payload",e);} }
}
